using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using System.Security.Cryptography;using AutosurBuscador;
class UpdateTests {
 static void Main(){string dir=Path.Combine(Path.GetTempPath(),"AutosurUpdates_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string valid=Path.Combine(dir,"valid.zip");using(var z=ZipFile.Open(valid,ZipArchiveMode.Create)){z.CreateEntry(UpdateManager.PackageFolder+"/Instalar.ps1");z.CreateEntry(UpdateManager.PackageFolder+"/app.cs");}UpdateManager.ValidatePackage(valid);Console.WriteLine("OK paquete de la aplicación");string invalid=Path.Combine(dir,"invalid.zip");using(var z=ZipFile.Open(invalid,ZipArchiveMode.Create)){z.CreateEntry(UpdateManager.PackageFolder+"/Instalar.ps1");z.CreateEntry(UpdateManager.PackageFolder+"/../escape.ps1");}bool rejected=false;try{UpdateManager.ValidatePackage(invalid);}catch{rejected=true;}if(!rejected)throw new Exception("Se aceptó una ruta fuera del paquete");Console.WriteLine("OK rechaza rutas fuera del paquete");string wrong=Path.Combine(dir,"wrong.zip");using(var z=ZipFile.Open(wrong,ZipArchiveMode.Create))z.CreateEntry("otra-app/Instalar.ps1");rejected=false;try{UpdateManager.ValidatePackage(wrong);}catch{rejected=true;}if(!rejected)throw new Exception("Se aceptó otra aplicación");Console.WriteLine("OK rechaza otra aplicación");
 string credential=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),UpdateManager.AppName,"datos","github-access.bin");byte[] old=File.Exists(credential)?File.ReadAllBytes(credential):null;try{string value="SYNTHETIC_TEST_VALUE_NOT_A_CREDENTIAL";UpdateManager.SaveAccess(value);var bytes=File.ReadAllBytes(credential);if(Encoding.UTF8.GetString(bytes).Contains(value))throw new Exception("El acceso no está cifrado");var decoded=Encoding.UTF8.GetString(ProtectedData.Unprotect(bytes,Encoding.UTF8.GetBytes(UpdateManager.Repository),DataProtectionScope.CurrentUser));if(decoded!=value)throw new Exception("No se pudo recuperar el acceso de prueba");Console.WriteLine("OK acceso cifrado DPAPI por usuario y repositorio");UpdateManager.SaveAccess("");if(File.Exists(credential))throw new Exception("No se eliminó el acceso de prueba");Console.WriteLine("OK quitar acceso guardado");}finally{if(old!=null)File.WriteAllBytes(credential,old);else if(File.Exists(credential))File.Delete(credential);}
 }finally{Directory.Delete(dir,true);}Console.WriteLine("Pruebas de actualización aprobadas.");}
}
